class Cache extends Map<string, number> {
  hits: number = 0;
  lookup(k: string): number {
    const v = this.get(k);
    if (v === undefined) { return -1; }
    this.hits++;
    return v;
  }
}
function main(): void {
  const c = new Cache();
  c.set("a", 1);
  console.log(c.lookup("a"), c.lookup("b"), c.hits, c.size);
}
